// Sampled involute flanks, radial root connections. Root fillets are simplified in this illustration.
function outline(){const z=24,rp=24,rb=rp*Math.cos(Math.PI/9),ra=26,rr=21.5,inv=a=>Math.tan(a)-a,half=Math.PI/(2*z)-0.1/(2*rp),baseHalf=half+inv(Math.PI/9);let pts=[];const point=(r,a)=>[260+5*r*Math.cos(a),220+5*r*Math.sin(a)];for(let i=0;i<z;i++){const a=2*Math.PI*i/z;pts.push(point(rr,a-baseHalf));for(let j=0;j<=8;j++){const r=rb+(ra-rb)*j/8;const t=Math.acos(rb/r);pts.push(point(r,a-baseHalf+inv(t)));}for(let j=8;j>=0;j--){const r=rb+(ra-rb)*j/8;const t=Math.acos(rb/r);pts.push(point(r,a+baseHalf-inv(t)));}pts.push(point(rr,a+baseHalf));const next=2*Math.PI*(i+1)/z-baseHalf;for(let j=1;j<=3;j++)pts.push(point(rr,a+baseHalf+(next-a-baseHalf)*j/3));}return 'M'+pts.map(p=>p.map(n=>n.toFixed(2)).join(',')).join('L')+'Z';}
export function gearGeometry(shape){if(shape==='gear-empty')return '<svg viewBox="0 0 855 403"><path d="M80 300H500M260 55V350" stroke="#ddd"/><circle cx="260" cy="300" r="3" fill="#555"/></svg>';const sketch=['gear-sketch','gear-circle'].includes(shape),path=outline();let g=`<defs><linearGradient id="gear-metal" x2="0" y2="1"><stop stop-color="#dedede"/><stop offset="1" stop-color="#aaa"/></linearGradient></defs>`;if(!sketch)g+=`<path d="${path}" transform="translate(0 12)" fill="#858585" stroke="#666"/>`;g+=`<path d="${path}" fill="url(#gear-metal)" stroke="#666"/><circle cx="260" cy="220" r="20" fill="#777" stroke="#555"/><ellipse cx="260" cy="225" rx="18" ry="14" fill="#fff"/>`;if(sketch)g+='<path d="M105 220H415M260 65V375" stroke="#b3b3b3" stroke-dasharray="4 4"/><circle cx="260" cy="220" r="3" fill="#555"/>';if(shape==='gear-circle')g+='<circle cx="320" cy="220" r="10" fill="#ead3ab88" stroke="#1556d4" stroke-width="2"/><circle cx="320" cy="220" r="2" fill="#1556d4"/><path d="M260 246V260H320V246" fill="none" stroke="#555"/><text x="282" y="278" font-size="12">12</text>';const n=shape==='gear-final'?6:shape==='gear-hole'?1:0;for(let i=0;i<n;i++){const a=2*Math.PI*i/6,x=260+60*Math.cos(a),y=220+60*Math.sin(a);g+=`<circle cx="${x}" cy="${y}" r="10" fill="#777" stroke="#555"/><ellipse cx="${x}" cy="${y+3}" rx="8" ry="6" fill="#fff"/>`;}return `<svg viewBox="0 0 855 403" preserveAspectRatio="none" aria-label="גלגל שיניים בעל 24 שיניים">${g}</svg>`;}
export function gearSpots(){const r=(x,y,w,h)=>[205+x,164+y,w,h];return {'gear-face':r(280,145,60,45),'gear-center':r(252,212,16,16),'gear-hole-center':r(312,212,16,16),'gear-hole-edge':r(325,213,12,14),'gear-hole-profile':r(313,213,14,14),'gear-dimension':r(277,252,28,22),'gear-bore-face':r(248,201,24,10),'gear-bore-edge':r(247,235,26,10)};}
